from AlgorithmImports import *


class IndependentSlotsStrategy(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma = self.sma(self.spy, 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.spy_sma_values = RollingWindow[float](2)
        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.rsi_threshold = 70

    def on_data(self, data: Slice):
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols):
            return

        spy_close = data.bars[self.spy].close
        aapl_close = data.bars[self.aapl].close

        if self.aapl in self.previous_closes:
            if aapl_close < self.previous_closes[self.aapl]:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        indicators_ready = self.spy_sma.is_ready and self.aapl_rsi.is_ready
        spy_cross_history_ready = self.spy_sma_values.count == 2
        aapl_red_history_ready = self.aapl in self.previous_closes

        if indicators_ready and spy_cross_history_ready and aapl_red_history_ready:
            yesterday_sma = self.spy_sma_values[0]
            today_sma = float(self.spy_sma.current.value)
            yesterday_spy_close = self.previous_closes[self.spy]

            # Sells are evaluated before buys.
            if self.strategy_a_shares > 0:
                if yesterday_spy_close >= yesterday_sma and spy_close < today_sma:
                    self.market_order(self.spy, -self.strategy_a_shares)
                    self.strategy_a_shares = 0

            if self.strategy_b_shares > 0:
                if float(self.aapl_rsi.current.value) > self.rsi_threshold:
                    self.market_order(self.aapl, -self.strategy_b_shares)
                    self.strategy_b_shares = 0

            if self.strategy_a_shares == 0:
                if yesterday_spy_close <= yesterday_sma and spy_close > today_sma:
                    shares = int((self.portfolio.total_portfolio_value * 0.40) // spy_close)
                    if shares > 0:
                        self.market_order(self.spy, shares)
                        self.strategy_a_shares = shares

            if self.strategy_b_shares == 0:
                if self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
                    shares = int(20_000 // aapl_close)
                    if shares > 0:
                        self.market_order(self.aapl, shares)
                        self.strategy_b_shares = shares

        self.spy_sma_values.add(float(self.spy_sma.current.value))

        for symbol in self.symbols:
            self.previous_closes[symbol] = data.bars[symbol].close
